async function a(b){const c=new TextEncoder().encode(b),d=await crypto.subtle.digest("SHA-256",c);return Array.from(new Uint8Array(d)).map(e=>e.toString(16).padStart(2,"0")).join("")}document.getElementById("registerForm")&&document.getElementById("registerForm").addEventListener("submit",async function(b){b.preventDefault();const c=document.getElementById("submitBtn");c.disabled=!0,c.textContent="Processing...";try{const d=await fetch("/pow-challenge"),e=await d.json(),f=e.challenge;document.getElementById("challenge").value=f;let g=0,h="";for(;!h.startsWith("0000");)h=await a(f+g),g++;document.getElementById("powNonce").value=g,this.submit()}catch(d){c.disabled=!1,c.textContent="Register",alert("An error occurred. Please try again.")}});document.getElementById("loginForm")&&document.getElementById("loginForm").addEventListener("submit",async function(b){b.preventDefault();const c=new FormData(this),d=await fetch("/login",{method:"POST",body:c}),e=await d.json();e.token&&(document.cookie=`token=${e.token}; path=/`,window.location.href=e.redirect)});
